template.script:
document.addEventListener('DOMContentLoaded', function() {
    cargarModelos();

    async function cargarModelos() {
        try {
            const response = await fetch('/api/modelos', {
                method: 'GET'
            });
            const modelos = await response.json();
            const selectModelo = document.getElementById('modelo');
            modelos.forEach(modelo => {
                let option = new Option(modelo.name, modelo.model);
                selectModelo.options.add(option);
            });
        } catch (error) {
            console.error('Error cargando modelos:', error);
        }
    }

    async function cargarCamposModelo() {
        try {
            const modelo = document.getElementById('modelo').value;
            const response = await fetch(`/api/campos?modelo=` + modelo, {
                method: 'GET'
            });
            const campos = await response.json();
            const selectCampos = document.getElementById('campos');
            selectCampos.innerHTML = '';  // Limpiar opciones existentes
            campos.forEach(campo => {
                let option = new Option(campo.name, campo.field);
                selectCampos.options.add(option);
            });
        } catch (error) {
            console.error('Error cargando campos:', error);
        }
    }

    window.cargarCamposModelo = cargarCamposModelo;  // Hacer global para acceso desde onchange

    window.configurarYObtenerDatos = async function() {
        try {
            const form = document.getElementById('form_grafico');
            const formData = new FormData(form);
            const data = {
                modelo: formData.get('modelo'),
                fecha_inicio: formData.get('fecha_inicio'),
                fecha_fin: formData.get('fecha_fin'),
                campos: [formData.get('campos')]
            };

            console.log('Enviando datos:', data);

            const response = await fetch('/api/grafico/datos', {
                method: 'POST',
                headers: {'Content-Type': 'application/json'},
                body: JSON.stringify(data)
            });

            const result = await response.json();

            console.log('Datos recibidos:', result);

            const ctx = document.getElementById('myChart').getContext('2d');
            new Chart(ctx, {
                type: 'bar',
                data: {
                    labels: result.labels,
                    datasets: result.datasets
                },
                options: {
                    scales: {
                        y: {
                            beginAtZero: true
                        }
                    }
                }
            });
        } catch (error) {
            console.error('Error configurando y obteniendo datos:', error);
        }
    };
});
